import{_ as e,o as r,c as t,a3 as l}from"./chunks/framework.BTt0kA_k.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"user/faq.md","filePath":"user/faq.md"}'),o={name:"user/faq.md"};function i(h,a,n,s,d,p){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="添加站点时为什么连接失败" tabindex="-1">添加站点时为什么连接失败 <a class="header-anchor" href="#添加站点时为什么连接失败" aria-label="Permalink to &quot;添加站点时为什么连接失败&quot;">​</a></h2><p>按顺序检查：</p><ol><li>接口协议是否与服务商说明一致。</li><li>对照请求地址预览，检查 Base URL 与端点直接拼接后是否与服务文档一致。</li><li>API Key 是否有效，是否有读取模型目录的权限。</li><li>服务商是否支持当前模型列表端点；需要时在添加窗口或高级设置中按文档修改。</li><li>该服务是否需要特殊路径或附加请求头。</li></ol><p>模型列表获取失败不会阻止保存站点。你可以保存后调整模型列表端点并重新同步，也可以手动添加模型。端点和协议请求字段按配置原文发送；如果服务商要求额外字段，请在探针策略的请求头或请求体中设置。</p><h2 id="为什么没有自动探测" tabindex="-1">为什么没有自动探测 <a class="header-anchor" href="#为什么没有自动探测" aria-label="Permalink to &quot;为什么没有自动探测&quot;">​</a></h2><p>检查应用是否仍在运行，并依次确认：</p><ol><li>“配置 → 通用设置 → 关闭主窗口后继续运行”已开启。</li><li>该站点开关已开启。</li><li>至少一个模型的探测开关已开启。</li><li>已等待站点“高级设置”中的探测间隔。</li><li>当前站点没有被同步、试探或其他任务占用。</li></ol><p>小面板底部的下次时间可以辅助判断。后台开关关闭时，即使主窗口打开也不会安排新的自动探测；退出应用后也不会继续工作。</p><h2 id="为什么-http-200-仍显示探测失败" tabindex="-1">为什么 HTTP 200 仍显示探测失败 <a class="header-anchor" href="#为什么-http-200-仍显示探测失败" aria-label="Permalink to &quot;为什么 HTTP 200 仍显示探测失败&quot;">​</a></h2><p>常规模型探测还要检查有效回答和协议完成标记。空回答、只有思考文本、被截断或缺失完成标记，都可能导致失败。</p><p>打开“运行 → 探测记录”的详情，查看原始返回。确认请求协议正确，再按服务商要求调整 Token 上限、推理参数或流式设置。自定义 HTTP 使用不同的判定口径，见<a href="./use/probes.html#成功与耗时的口径">探针配置</a>。</p><h2 id="为什么有失败记录-小面板还没转红" tabindex="-1">为什么有失败记录，小面板还没转红 <a class="header-anchor" href="#为什么有失败记录-小面板还没转红" aria-label="Permalink to &quot;为什么有失败记录，小面板还没转红&quot;">​</a></h2><p>记录是单次请求的结果，小面板按连续失败、连续恢复规则显示稳定状态。新建站点默认连续失败 <strong>3 次</strong>转红，转红后连续成功 <strong>2 次</strong>恢复。</p><p>已有稳定状态时，未达到失败阈值前会保留之前的状态；尚无稳定状态且失败未达到阈值时显示“待确认”。首次成功可直接显示正常或偏慢。</p><h2 id="为什么首-token-或-token-用量是横线" tabindex="-1">为什么首 Token 或 Token 用量是横线 <a class="header-anchor" href="#为什么首-token-或-token-用量是横线" aria-label="Permalink to &quot;为什么首 Token 或 Token 用量是横线&quot;">​</a></h2><ul><li>非流式或自定义 HTTP 请求不提供首 Token 耗时。</li><li>没有收到可计时的有效文本时，首 Token 可能缺失。</li><li>服务商没有明确上报 <code>usage</code> 时，Token 用量缺失。</li></ul><p>横线 <code>—</code> 表示没有数据，不表示零耗时或免费。用量不完整时，以服务商后台和账单为准。</p><h2 id="为什么模型操作按钮不能点击" tabindex="-1">为什么模型操作按钮不能点击 <a class="header-anchor" href="#为什么模型操作按钮不能点击" aria-label="Permalink to &quot;为什么模型操作按钮不能点击&quot;">​</a></h2><p>先检查站点基本信息是否有未保存更改，保存后再操作模型。再确认该站点是否正在探测、同步、试探或保存。同一站点的任务会互斥，等待当前任务结束后重试。</p><h2 id="试探通过了-为什么记录里没有结果" tabindex="-1">试探通过了，为什么记录里没有结果 <a class="header-anchor" href="#试探通过了-为什么记录里没有结果" aria-label="Permalink to &quot;试探通过了，为什么记录里没有结果&quot;">​</a></h2><p>模型自定义请求中的“试探一次”验证的是当前草稿，不写入正式探测历史，也不自动保存设置。点击“保存”后，再发起一次正式探测。</p><h2 id="为什么小面板只显示三个模型" tabindex="-1">为什么小面板只显示三个模型 <a class="header-anchor" href="#为什么小面板只显示三个模型" aria-label="Permalink to &quot;为什么小面板只显示三个模型&quot;">​</a></h2><p>小面板最多展示 3 个模型，并按站点顺序组织。点击“查看全部”到站点管理查看其余模型；需要改变优先显示的站点时，可以调整站点顺序。</p><h2 id="为什么收不到通知" tabindex="-1">为什么收不到通知 <a class="header-anchor" href="#为什么收不到通知" aria-label="Permalink to &quot;为什么收不到通知&quot;">​</a></h2><p>先检查“启用消息通知”、对应规则开关和系统权限，再发送测试通知。已授权但仍没有通知时，检查 macOS 通知设置与专注模式。</p><p>模型故障和恢复通知依据稳定状态变化，未达到阈值的单次失败不会立即发送。</p><h2 id="为什么智商测试不能开始" tabindex="-1">为什么智商测试不能开始 <a class="header-anchor" href="#为什么智商测试不能开始" aria-label="Permalink to &quot;为什么智商测试不能开始&quot;">​</a></h2><p>至少选择一道启用的题目，添加一个参与者，并确认所有参与者预检为“可用”。失败重试次数须为 0–20 的整数。</p><p>没有候选模型时，先去站点管理启用模型；预检失败时查看提示、调整配置，再重新探测或重新添加参与者。</p><h2 id="智商测试显示成功-是答对了吗" tabindex="-1">智商测试显示成功，是答对了吗 <a class="header-anchor" href="#智商测试显示成功-是答对了吗" aria-label="Permalink to &quot;智商测试显示成功，是答对了吗&quot;">​</a></h2><p>成功表示请求完成，不是答案判分。请结合题面、参考答案和输出回放人工判断。失败重试针对请求报错，不针对答案正确与否。</p><h2 id="升级后要求迁移-应该怎么做" tabindex="-1">升级后要求迁移，应该怎么做 <a class="header-anchor" href="#升级后要求迁移-应该怎么做" aria-label="Permalink to &quot;升级后要求迁移，应该怎么做&quot;">​</a></h2><p>按<a href="./use/data.html#升级时提示迁移旧版本数据">本地数据与版本升级</a>使用“备份并迁移”。迁移期间保持应用运行；有失败提示时保留原数据与错误信息。</p><h2 id="怎样反馈问题" tabindex="-1">怎样反馈问题 <a class="header-anchor" href="#怎样反馈问题" aria-label="Permalink to &quot;怎样反馈问题&quot;">​</a></h2><p>记录应用版本、macOS 版本、问题发生时间、操作步骤、预期结果和实际错误。需要排查日志时，在“配置 → 通用设置”导出诊断包。</p><p>可通过 <a href="https://github.com/skyzfdance/RelayPulse/issues" target="_blank" rel="noreferrer">GitHub Issues</a>反馈。截图前隐藏 API Key 等凭据；涉及模型输出或题目内容时，确认哪些内容适合公开。</p>',37)])])}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
